"""Fixed-width EXPORT_ACCT record formatter."""

from decimal import Decimal, ROUND_HALF_UP


def _value(row: dict, key: str) -> object:
    value = row.get(key, "")
    return "" if value is None else value


def _fixed(value: object, width: int) -> str:
    text = str(value)
    return text[:width].ljust(width)


def _zpad_cents(value: object, width: int) -> str:
    cents = (Decimal(str(value)) * Decimal("100")).to_integral_value(
        rounding=ROUND_HALF_UP
    )
    return format(int(cents), f"0{width}d")


def format_account(row: dict) -> str:
    """Return the 77-character legacy EXPORT_ACCT fixed-width record."""
    ann_rev = _value(row, "ANN_REV")
    if ann_rev == "":
        ann_rev = 0

    cred_hold = _value(row, "CRED_HOLD")
    if cred_hold == "":
        cred_hold = "N"

    create_dt = _value(row, "CREATE_DT")
    if create_dt == "":
        create_dt = "00000000"

    return (
        _fixed(_value(row, "ACCT_ID"), 10)
        + _fixed(_value(row, "ACCT_NM"), 40)
        + _fixed(_value(row, "REGION_CD"), 3)
        + _zpad_cents(ann_rev, 15)
        + str(cred_hold)
        + str(create_dt)
    )
